    protected void readAdditionalSaveData(CompoundTag tag) {
        if (tag.hasUUID("ControllerUUID")) {
            this.setControllerUUID(tag.getUUID("ControllerUUID"));
        }
        this.setDuration(tag.getInt("Duration"));
