		super(properties);
		this.isDisabled = isDisabled;
	}

	@Override
	public void addCreativeTabItems(Consumer<ItemStack> itemConsumer) {
		if (Boolean.TRUE.equals(isDisabled.get())) {
			return;
		}

		itemConsumer.accept(new ItemStack(this));
	}

