package com.stal111.forbidden_arcanus.core.mixin;

import com.llamalad7.mixinextras.injector.ModifyReturnValue;
import com.stal111.forbidden_arcanus.common.item.component.EffectGrantingRule;
import com.stal111.forbidden_arcanus.core.init.ModDataComponents;
import net.minecraft.core.Holder;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.Nullable;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * @author stal111
 * @since 10.09.2023
 */
@Mixin(LivingEntity.class)
public abstract class LivingEntityMixin extends Entity {

    @Unique
    @Nullable
    private List<EffectGrantingRule> forbiddenArcanus$activeEffectRules;

    public LivingEntityMixin(EntityType<?> entityType, Level level) {
        super(entityType, level);
    }

    @Shadow
    public abstract ItemStack getItemBySlot(EquipmentSlot pSlot);

    @Inject(at = @At(value = "HEAD"), method = "onEquipItem")
    private void forbiddenArcanus_onEquipItem(EquipmentSlot slot, ItemStack oldStack, ItemStack stack, CallbackInfo ci) {
        this.forbiddenArcanus$activeEffectRules = null;
    }

    @Inject(at = @At(value = "RETURN"), method = "collectEquipmentChanges")
    private void forbiddenArcanus_collectEquipmentChanges(CallbackInfoReturnable<Map<EquipmentSlot, ItemStack>> cir) {
        if (cir.getReturnValue() != null) {
            this.forbiddenArcanus$activeEffectRules = null;
        }
    }

    @ModifyReturnValue(at = @At(value = "RETURN"), method = "hasEffect")
    public boolean forbiddenArcanus_hasEffect$grantEffects(boolean original, Holder<MobEffect> effect) {
        if (original || !(this.level() instanceof ServerLevel serverLevel)) {
            return original;
        }

        List<EffectGrantingRule> rules = this.forbiddenArcanus$getActiveEffectRules();
        if (rules.isEmpty()) {
            return false;
        }

        for (EffectGrantingRule rule : rules) {
            if (rule.shouldGrantEffect(serverLevel, effect, (LivingEntity) (Object) this)) {
                return true;
            }
        }

        return false;
    }

    @Unique
    private List<EffectGrantingRule> forbiddenArcanus$getActiveEffectRules() {
        List<EffectGrantingRule> cached = this.forbiddenArcanus$activeEffectRules;
        if (cached != null) {
            return cached;
        }

        List<EffectGrantingRule> activeRules = null;

        for (EquipmentSlot slot : EquipmentSlot.VALUES) {
            ItemStack stack = this.getItemBySlot(slot);
            if (stack.isEmpty()) {
                continue;
            }

            List<EffectGrantingRule> rules = stack.getOrDefault(ModDataComponents.GRANTS_EFFECTS, List.of());
            for (EffectGrantingRule rule : rules) {
                if (rule.slot().test(slot)) {
                    if (activeRules == null) {
                        activeRules = new ArrayList<>();
                    }
                    activeRules.add(rule);
                }
            }
        }

        cached = activeRules != null ? List.copyOf(activeRules) : List.of();
        this.forbiddenArcanus$activeEffectRules = cached;
        return cached;
    }
}

package com.stal111.forbidden_arcanus.common.event;

import com.stal111.forbidden_arcanus.common.entity.attribute.FAAttributes;
import com.stal111.forbidden_arcanus.common.essence.EssenceHelper;
import com.stal111.forbidden_arcanus.common.item.modifier.BuiltInItemModifiers;
import com.stal111.forbidden_arcanus.common.item.modifier.ModifierHelper;
import com.stal111.forbidden_arcanus.common.item.modifier.SoulboundInventory;
import com.stal111.forbidden_arcanus.core.init.ModItems;
import com.stal111.forbidden_arcanus.core.init.other.ModAttachmentTypes;
import com.stal111.forbidden_arcanus.util.ModTags;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.damagesource.DamageTypes;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.EntityAttributeModificationEvent;
import net.neoforged.neoforge.event.entity.living.LivingDamageEvent;
import net.neoforged.neoforge.event.entity.living.LivingDeathEvent;

@EventBusSubscriber
public class EntityEvents {

    @SubscribeEvent
    public static void onAttributeModification(EntityAttributeModificationEvent event) {
        event.add(EntityType.PLAYER, FAAttributes.AUREAL_REGENERATION);
    }

    @SubscribeEvent
    public static void onEntityDamage(LivingDamageEvent.Post event) {
        DamageSource source = event.getSource();

        if (source.is(DamageTypes.PLAYER_ATTACK) && source.getEntity() instanceof Player player && !event.getEntity().is(ModTags.EntityTypes.TEST_TUBE_BLACKLISTED)) {
            if (player.getOffhandItem().is(ModItems.TEST_TUBE)) {
                player.setItemInHand(InteractionHand.OFF_HAND, ModItems.BLOOD_TEST_TUBE.get().getDefaultInstance());
            }

            ItemStack stack = player.getOffhandItem();

            if (stack.is(ModTags.Items.RECEIVES_BLOOD)) {
                EssenceHelper.getEssenceStorage(stack).ifPresent(storage -> {
                    storage.addEssence(stack, (int) (20 * event.getHealthDamage()));
                });
            }
        }
    }

    @SubscribeEvent
    public static void onLivingDeath(LivingDeathEvent event) {
        if (event.getEntity() instanceof ServerPlayer player) {
            SoulboundInventory inventory = SoulboundInventory.create();

            for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
                ItemStack stack = player.getInventory().getItem(i);

                if (ModifierHelper.hasModifier(stack, player.level().holderOrThrow(BuiltInItemModifiers.SOULBOUND))) {
                    inventory.add(i, stack);

                    player.getInventory().setItem(i, ItemStack.EMPTY);
                }
            }

            player.setData(ModAttachmentTypes.SOULBOUND_INVENTORY, inventory);
        }
    }
}

package com.stal111.forbidden_arcanus.common.item.component;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import com.stal111.forbidden_arcanus.common.advancements.critereon.EssenceValueEntityPredicate;
import com.stal111.forbidden_arcanus.common.essence.EssenceType;
import com.stal111.forbidden_arcanus.common.essence.EssenceValue;
import net.minecraft.advancements.criterion.EntityPredicate;
import net.minecraft.core.Holder;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EquipmentSlotGroup;

import java.util.Optional;

public record EffectGrantingRule(Holder<MobEffect> effect, EquipmentSlotGroup slot, Optional<EntityPredicate> predicate) {

    public static final Codec<EffectGrantingRule> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            MobEffect.CODEC.fieldOf("effects").forGetter(EffectGrantingRule::effect),
            EquipmentSlotGroup.CODEC.fieldOf("slot").forGetter(EffectGrantingRule::slot),
            EntityPredicate.CODEC.optionalFieldOf("predicate").forGetter(EffectGrantingRule::predicate)
    ).apply(instance, EffectGrantingRule::new));

    public static final EffectGrantingRule GRANT_FIRE_RESISTANCE = new EffectGrantingRule(MobEffects.FIRE_RESISTANCE, EquipmentSlotGroup.HEAD, Optional.empty());
    public static final EffectGrantingRule GRANT_FIRE_RESISTANCE_IF_HAS_AUREAL = new EffectGrantingRule(MobEffects.FIRE_RESISTANCE, EquipmentSlotGroup.HEAD, Optional.of(EntityPredicate.Builder.entity().subPredicate(new EssenceValueEntityPredicate(EssenceValue.of(EssenceType.AUREAL, 1))).build()));

    public boolean shouldGrantEffect(ServerLevel level, Holder<MobEffect> effect, Entity entity) {
        return this.effect().is(effect) && this.entityMatches(level, entity);
    }

    private boolean entityMatches(ServerLevel level, Entity entity) {
        return this.predicate
                .map(predicate -> predicate.matches(level, null, entity))
                .orElse(true);
    }
}

